function buildSermon(s: SermonSeed): Sermon {
  const fullText = s.sections.map((sec) => `${sec.heading}\n${sec.body}`).join("\n\n");
  const now = new Date("2026-01-01").toISOString();
  return {
    id: s.id,
    title: s.title,
    slug: s.id,
    contentType: s.contentType,
    excerpt: s.excerpt,
    fullText,
    normalizedText: normalizeArabic(`${s.title}\n${fullText}\n${s.tags.join(" ")}`),
    categorySlug: s.categorySlug,
    categoryName: s.categoryName,
    tags: s.tags,
    language: "ar",
    contentStatus: "published",
    createdAt: now,
    updatedAt: now,
    isGenerated: false,
    sections: s.sections,
    estimatedMinutes: s.estimatedMinutes,
  };
}

export const SERMONS: Sermon[] = SEEDS.map(buildSermon);

export function getSermonsByCategory(slug: string): Sermon[] {
  return SERMONS.filter((s) => s.categorySlug === slug);
}

export function getSermonById(id: string): Sermon | undefined {
  return SERMONS.find((s) => s.id === id);
}

export function countSermonsByCategory(slug: string): number {
  return SERMONS.filter((s) => s.categorySlug === slug).length;
}
